CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL DEFAULT 'Player' CHECK (length(username) BETWEEN 1 AND 60), phone text NOT NULL DEFAULT '', balance numeric(14,2) NOT NULL DEFAULT 0 CHECK (balance >= 0), status text NOT NULL DEFAULT 'active', vip boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE(username,phone) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,username) VALUES(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'Player'),60)); RETURN new; END; $$;
CREATE TRIGGER create_player_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE TABLE public.payment_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('deposit','withdrawal')), amount numeric(14,2) NOT NULL CHECK(amount>0), method text NOT NULL CHECK(method IN ('bKash','Nagad')), account_number text NOT NULL DEFAULT '' CHECK(length(account_number)<=30), transaction_id text CHECK(length(transaction_id)<=80), proof_path text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reserved boolean NOT NULL DEFAULT false, review_reason text, reviewed_at timestamptz, reviewed_by uuid, payout_reference text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(kind<>'deposit' OR (transaction_id IS NOT NULL AND length(transaction_id)>0 AND proof_path IS NOT NULL)));
GRANT SELECT ON public.payment_requests TO authenticated;
GRANT ALL ON public.payment_requests TO service_role;
ALTER TABLE public.payment_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_request_read ON public.payment_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.site_notices(id text PRIMARY KEY, message text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_notices TO anon,authenticated;
GRANT ALL ON public.site_notices TO service_role;
ALTER TABLE public.site_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_notice ON public.site_notices FOR SELECT TO anon,authenticated USING(active);
CREATE TABLE public.content_banners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, storage_path text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.content_banners TO anon,authenticated;
GRANT ALL ON public.content_banners TO service_role;
ALTER TABLE public.content_banners ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_banner ON public.content_banners FOR SELECT TO anon,authenticated USING(active);
CREATE TABLE public.payment_gateways(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), method text NOT NULL CHECK(method IN ('bKash','Nagad')), account_number text NOT NULL, account_type text NOT NULL DEFAULT 'personal', active boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.payment_gateways TO anon,authenticated;
GRANT ALL ON public.payment_gateways TO service_role;
ALTER TABLE public.payment_gateways ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_gateway ON public.payment_gateways FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY own_receipt_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='payment-receipts' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('png','jpg','jpeg','webp'));
CREATE POLICY own_receipt_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='payment-receipts' AND (storage.foldername(name))[1]=auth.uid()::text);
ALTER PUBLICATION supabase_realtime ADD TABLE public.profiles,public.payment_requests,public.site_notices,public.content_banners;